#!/usr/bin/env python3
"""Original SVG research schematics and A3 portrait HTML; no game asset changes."""
from pathlib import Path
import math
HERE=Path(__file__).resolve().parent
PLAN=HERE.parents[1]/'plans/2026-10-05-sea-anemone-realism'
PLAN.mkdir(parents=True,exist_ok=True)
INK='#173b43'
def svg(body,w=1000,h=350):
 return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {w} {h}" role="img">{body}</svg>'
def text(x,y,s,size=23):
 return f'<text x="{x}" y="{y}" font-family="sans-serif" font-size="{size}" fill="{INK}">{s}</text>'
def animal(cx=500,cy=265,scale=1,flow=0,retract=0):
 s=[f'<g transform="translate({cx},{cy}) scale({scale})">', '<path d="M-230 22 Q-170 -12 -105 8 Q-40 -35 28 -12 Q140 -30 232 20 L245 60 L-250 60Z" fill="#738483"/>', '<path d="M-63 17 Q-58 -10 -46 -75 Q-88 -96 -106 -104 Q0 -144 106 -104 Q62 -82 47 -72 Q55 -5 67 17Z" fill="#a65569" stroke="#753e54" stroke-width="3"/>','<ellipse cx="0" cy="-100" rx="109" ry="29" fill="#a77669"/><ellipse cx="0" cy="-105" rx="23" ry="7" fill="#693947"/>']
 for i in range(40):
  a=i*2.399963; r=30+75*math.sqrt((i+.5)/40); x=math.cos(a)*r; y=-103+math.sin(a)*r*.22
  ln=(57+((i*17)%55))*(1-.67*retract); bend=math.sin(a)*30+flow*ln*.65
  tx=x+bend; ty=y-ln; col=['#b75b75','#c36d7f','#99686a','#b17972'][i%4]
  s.append(f'<path d="M{x:.1f} {y:.1f} C{x+bend*.15:.1f} {y-ln*.35:.1f} {tx-bend*.25:.1f} {ty+ln*.18:.1f} {tx:.1f} {ty:.1f}" fill="none" stroke="{col}" stroke-width="{8+i%4}" stroke-linecap="round"/>')
  if i%4!=0:s.append(f'<ellipse cx="{tx:.1f}" cy="{ty+5:.1f}" rx="{7+i%3}" ry="11" fill="{col}"/><circle cx="{tx+1:.1f}" cy="{ty+1:.1f}" r="3" fill="#e1b1a5"/>')
 s.append('</g>');return ''.join(s)
anatomy=svg('<rect width="1000" height="360" rx="18" fill="#edf3ef"/>'+animal(490,285)+text(28,44,'BUBBLE-TIP · Entacmaea quadricolor',25)+text(26,95,'Soft curved tentacles')+'<path d="M255 91 L407 128" stroke="#237c83" fill="none"/>'+text(725,142,'Oral disc + mouth')+'<path d="M735 150 L520 185" stroke="#237c83" fill="none"/>'+text(695,226,'Fluid-supported column',21)+text(30,314,'Pedal disc in a crevice')+'<path d="M278 303 L440 294" stroke="#237c83" fill="none"/>',1000,360)
flow=svg('<rect width="1000" height="310" rx="18" fill="#edf3ef"/>'+animal(210,240,.73,0)+animal(720,240,.73,.9)+text(42,38,'ACTIVE SHAPE + PASSIVE FLOW',24)+text(60,292,'Calm: curved, inflated tissue')+text(570,292,'Flow: shared lean, lagging tips')+'<path d="M505 70 L910 70 L888 56 M910 70 L888 84" stroke="#237c83" stroke-width="5" fill="none"/>',1000,310)
loc=['<rect width="1000" height="240" rx="18" fill="#edf3ef"/>']
for i,label in enumerate(['Attach','Extend edge','Shift load','Reattach']):
 x=125+i*250
 loc += [f'<path d="M{x-90} 162 H{x+85}" stroke="#738483" stroke-width="12"/>',f'<path d="M{x-57} 150 Q{x-38} 122 {x-25} 81 Q{x+20} 59 {x+37+i*7} 86 L{x+48+i*7} 147Z" fill="#b5757d"/>',f'<path d="M{x-55+i*5} 152 H{x+35+i*12}" stroke="#237c83" stroke-width="6"/>',text(x-90,213,label)]
locomotion=svg(''.join(loc),1000,240)
curve=['<rect width="1000" height="280" rx="18" fill="#edf3ef"/>']
for k,(label,b) in enumerate([('Root stays fixed',0),('Tip follows water',70),('Local contraction',-35)]):
 x=140+k*330; length=150 if k<2 else 95
 curve += [f'<path d="M{x} 221 C{x} 173 {x+b*.15} {221-length*.75} {x+b} {221-length}" stroke="#b2697b" stroke-width="17" fill="none" stroke-linecap="round"/>',f'<circle cx="{x}" cy="221" r="9" fill="#237c83"/>',text(x-105,263,label,22)]
curve=svg(''.join(curve),1000,280)
mesh=svg('''<rect width="1000" height="260" rx="18" fill="#edf3ef"/><g stroke="#91586b" fill="none" stroke-width="2"><path d="M120 225 Q105 110 163 35 L190 35 Q136 115 146 225Z"/><path d="M127 225 Q116 115 172 35 M137 225 Q126 115 181 35"/><path d="M117 188 L143 188 M115 157 L145 157 M122 122 L155 122 M138 86 L168 86 M157 52 L182 52"/></g><path d="M349 225 Q325 90 397 52 Q408 35 422 49 Q447 72 416 89 Q374 134 375 225Z" fill="#b6697c"/><g fill="#dca48d"><circle cx="407" cy="65" r="4"/><circle cx="411" cy="76" r="3"/><circle cx="385" cy="130" r="2"/><circle cx="366" cy="179" r="2"/></g><rect x="574" y="30" width="365" height="172" rx="8" fill="#b07772"/><g stroke="#d5a28c" opacity=".8" fill="none"><path d="M600 35 Q645 100 623 197 M650 35 Q690 100 683 197 M710 35 Q735 110 746 197 M770 35 Q790 100 806 197 M835 35 Q850 100 868 197"/></g>'''+text(36,253,'Curved tube topology',22)+text(316,253,'Continuous fleshy tip',22)+text(600,253,'256² atlas · fine markings',22),1000,260)
control=svg('<rect width="1000" height="340" rx="18" fill="#112f3a"/>'+animal(400,245,.9,.35)+ '<g font-family="sans-serif" fill="#ecf2e9"><text x="40" y="45" font-size="27">Clownfish &amp; Anemone · proposed control focus</text><rect x="705" y="78" width="260" height="174" rx="14" fill="#224c57"/><text x="725" y="110" font-size="22">Control: Anemone</text><text x="725" y="153" font-size="20">D-pad · crawl on rock</text><text x="725" y="190" font-size="20">Hold A · withdraw</text><text x="725" y="227" font-size="20">Release · re-expand</text><text x="40" y="316" font-size="21">↶ Selector       Foot attached · gentle flow       Settings: switch control focus</text></g>',1000,340)
state=svg('''<rect width="1000" height="220" rx="18" fill="#edf3ef"/><g fill="#dbe8de" stroke="#237c83"><rect x="25" y="50" width="185" height="80" rx="12"/><rect x="282" y="50" width="190" height="80" rx="12"/><rect x="550" y="50" width="190" height="80" rx="12"/><rect x="810" y="50" width="170" height="80" rx="12"/></g>'''+text(50,98,'SETTLED')+text(310,98,'CRAWLING')+text(574,98,'WITHDRAWN')+text(829,98,'RECOVER')+'<path d="M210 90 H280 M472 90 H548 M740 90 H808" stroke="#237c83" stroke-width="3"/>'+text(30,188,'Input chooses intent; attachment and motion envelopes constrain the pose.',22),1000,220)
arts={'anatomy.svg':anatomy,'tentacle-motion.svg':flow,'pedal-locomotion.svg':locomotion,'curve-response.svg':curve,'mesh-texture.svg':mesh,'controls-mockup.svg':control,'state-diagram.svg':state}
for name,data in arts.items():
 (HERE/name).write_text(data);(PLAN/name).write_text(data)
refs=[('1','Titus et al. · bubble-tip morphology (2024)','https://publication.plazi.org/GgServer/xhtml/038187876444FFCC1BD2F8B1FB9475D8'),('2','Watson et al. · bubble-tip relocation (2022)','https://onlinelibrary.wiley.com/doi/10.1111/are.15786'),('3','Full et al. · Aiptasia field flow, SICB abstract (2013)','https://sicb.org/abstracts/sea-anemone-tentacles-flutter-and-flap-in-water-flow-in-the-field/'),('4','Clarke et al. · Exaiptasia adhesion (2020)','https://link.springer.com/article/10.1186/s40850-020-00054-6'),('5','Robson · Stomphia swimming (1961)','https://doi.org/10.1242/jeb.38.2.343'),('6','Cnidarian muscles review (2017)','https://pmc.ncbi.nlm.nih.gov/articles/PMC5253434/')]
html='''<!doctype html><html lang="en"><meta charset="utf-8"><title>Sea anemones · A3 research poster</title><style>
@page{size:A3 portrait;margin:0}*{box-sizing:border-box}body{margin:0;background:#cbd5d1;color:#173b43;font-family:"DejaVu Sans",sans-serif}.page{width:297mm;height:420mm;padding:11mm 12mm;background:#f8f7ef;margin:auto;display:flex;flex-direction:column;gap:4mm}header{border-bottom:3px solid #237c83;padding-bottom:3mm}h1{font-size:35pt;margin:0;letter-spacing:-1px}h2{font-size:14pt;margin:0 0 2mm}p{font-size:10.3pt;line-height:1.4;margin:1.5mm 0}.strap{font-size:13pt;color:#6e4558}.hero{height:93mm;display:grid;grid-template-columns:1.8fr 1fr;gap:5mm;align-items:center}.hero svg{width:100%}.row{display:grid;grid-template-columns:1fr 1fr;gap:5mm}.panel{background:#edf3ef;border-radius:3mm;padding:3.5mm}.panel svg{width:100%;display:block}.bottom{background:#173b43;color:#f3f1e8;padding:4mm;border-radius:3mm}.bottom .row{gap:6mm}.bottom h2{color:#cde2d0}pre{font-size:10pt;line-height:1.5;margin:1mm 0;font-family:"DejaVu Sans Mono",monospace}footer{margin-top:auto;font-size:8.4pt;line-height:1.45}a{color:inherit}.tag{font-size:8.8pt;font-weight:bold;color:#237c83}.caption{font-size:9pt;color:#65544e}
@media screen{.page{box-shadow:0 5px 30px #476158;margin:20px auto}}@media print{body{background:white}.page{margin:0;box-shadow:none}}</style><main class="page"><header><div class="strap">LIVING TISSUE · ADHESIVE BASE · MOVING WATER</div><h1>Sea anemones</h1><p>Slow journeys. Flexible tentacles. A fluid-supported body.</p></header>
<section class="hero">ANATOMY<div><h2>Soft tentacles, not spines</h2><p>Muscular tissue bends, shortens and extends against fluid pressure. Stinging cells are microscopic; the visible crown is soft. [6]</p><p>Our focus: <i>Entacmaea quadricolor</i>, the bubble-tip. Dense, uneven tentacles can mix swollen and slender tips. The foot is usually hidden in a rock crevice. [1]</p><p class="tag">BIOLOGY FIRST · SCHEMATICS BELOW</p></div></section>
<div class="row"><section class="panel"><h2>01 · A foot that can relocate</h2>FOOT<p>Adults can move to new positions in an aquarium. Daily observations confirm relocation, but do not give a crawling speed. [2]</p><p>Foot adhesion is studied in <i>Exaiptasia</i>. [4] This moving-attachment sequence is a visual approximation, pending bubble-tip footage.</p></section><section class="panel"><h2>02 · Flow gives a shared rhythm</h2>FLOW<p>Field observations of <i>Aiptasia diaphana</i> show downstream bending and wave-linked flutter; long tentacles make larger excursions. [3]</p><p>For sheltered bubble-tips: gentle coherent lean, curved tips and local lag. This transfer is a modeling inference.</p></section></div>
<div class="row"><section class="panel"><h2>03 · Muscles change the shape</h2>CURVE<p>Layer active shortening and recovery onto water motion. Roots remain attached to the disc; tips respond more visibly. [6]</p><p><i>Stomphia</i> can detach and swim after particular predator stimuli. [5] That is a separate species' behavior, not the bubble-tip default.</p></section><section class="panel"><h2>04 · A continuous fleshy surface</h2>MESH<p>Use curved tube geometry, blunt tips, uneven bulbs and a dense crown. Striation, speckles and translucency are documented in bubble-tips. [1]</p><p class="caption">256² texture atlas is a proposed game choice. Fine markings belong in the texture; silhouette and bending need geometry.</p></section></div>
<section class="bottom"><h2>05 · Small Forth ideas, richer motion</h2><div class="row"><div><pre>\\ Normalized root-to-tip coordinate
: tip-weight ( u -- w ) dup * ;
\\ First-order response; tau > 0
: lag-step ( x target dt tau -- x' )
  / 1 min 0 max >r over -
  r> * + ;</pre></div><div><p>One shared water signal; length-dependent tip response; sparse local contractions. Avoid one actor or mailbox loop per tentacle.</p><p><b>Proposed controls:</b> D-pad crawls on valid rock; hold A withdraws, release allows recovery. Switch control focus in settings. No fish-like dart.</p><p>These fragments are illustrative, not a complete rig. Speeds, periods and response times need footage and profiling.</p></div></div></section>
<footer><b>Research saved first:</b> <a href="../sea-anemone-research.md">sea-anemone-research.md</a> · Checked 5 October 2026.<br>SOURCES<br>REFS<br>A3 portrait · 297 × 420 mm · Original editable vector schematics, not photographs or implemented assets. Cross-species evidence is labelled. Biology and proposed game behavior are distinct.</footer></main></html>'''
for key,art in [('ANATOMY',anatomy),('FOOT',locomotion),('FLOW',flow),('CURVE',curve),('MESH',mesh)]:html=html.replace(key,art)
html=html.replace('REFS',' · '.join(f'<a href="{url}">[{n}] {label}</a>' for n,label,url in refs))
(HERE/'poster.html').write_text(html)
print(HERE/'poster.html')
